(function (window, document) {
  'use strict';

  if (!window.L) { return; }
  var L = window.L;

  // ------------------------------------------------------------------------
  // Google Maps (Map Tiles API): Working حين يضع Platform admin or Owner of Account Key Google,
  // وإلا تبقى الخرائط Open كما هي. الجلسة تُحفظ in المتصفح until انتهائها فلا تُطلب مع Every Page.
  // ------------------------------------------------------------------------
  var geoCfg = (function () {
    var n = document.querySelector('[data-sn-geo]');
    try { return n ? JSON.parse(n.textContent) : {}; } catch (e) { return {}; }
  })();
  var GKEY = geoCfg.google || '';
  var GAPI = 'https://tile.googleapis.com';
  var sessions = {};
  var googleFailed = false;

  function googleSession(kind) {
    if (sessions[kind]) { return sessions[kind]; }
    var body = { mapType: kind === 'hybrid' ? 'satellite' : kind, language: geoCfg.lang === 'en' ? 'en' : 'ar', region: geoCfg.region || 'PS' };
    if (kind === 'hybrid') { body.layerTypes = ['layerRoadmap']; }
    if (kind === 'terrain') { body.layerTypes = ['layerRoadmap']; }
    if ((window.devicePixelRatio || 1) > 1.4) { body.scale = 'scaleFactor2x'; body.highDpi = true; }
    var store = 'sn-gtiles:' + GKEY.slice(-8) + ':' + JSON.stringify(body);
    try {
      var saved = JSON.parse(localStorage.getItem(store) || 'null');
      if (saved && saved.session && +saved.expiry - 3600 > Date.now() / 1000) {
        sessions[kind] = Promise.resolve(saved);
        return sessions[kind];
      }
    } catch (e) { /* Storage Unavailable */ }
    sessions[kind] = fetch(GAPI + '/v1/createSession?key=' + encodeURIComponent(GKEY), {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
    }).then(function (r) {
      return r.json().catch(function () { return {}; }).then(function (j) {
        if (!r.ok || !j.session) { throw new Error((j.error && j.error.message) || ('HTTP ' + r.status)); }
        try { localStorage.setItem(store, JSON.stringify(j)); } catch (e) { /* Storage Unavailable */ }
        return j;
      });
    });
    sessions[kind].catch(function () { delete sessions[kind]; });
    return sessions[kind];
  }

  var GoogleLayer = L.TileLayer.extend({
    initialize: function (kind, options) {
      this._kind = kind;
      L.TileLayer.prototype.initialize.call(this, '', L.extend({ maxZoom: 21, maxNativeZoom: kind === 'roadmap' ? 21 : 20, className: 'tiles-google tiles-' + kind }, options));
    },
    createTile: function (coords, done) {
      var tile = document.createElement('img');
      L.DomEvent.on(tile, 'load', L.Util.bind(this._tileOnLoad, this, done, tile));
      L.DomEvent.on(tile, 'error', L.Util.bind(this._tileOnError, this, done, tile));
      tile.alt = '';
      tile.setAttribute('role', 'presentation');
      var z = this._getZoomForUrl();
      googleSession(this._kind).then(function (s) {
        tile.src = GAPI + '/v1/2dtiles/' + z + '/' + coords.x + '/' + coords.y + '?session=' + encodeURIComponent(s.session) + '&key=' + encodeURIComponent(GKEY);
      }, function (err) { done(err, tile); });
      return tile;
    },
    onAdd: function (map) {
      L.TileLayer.prototype.onAdd.call(this, map);
      var self = this;
      this._credit = function () { self._updateCredit(); };
      map.on('moveend', this._credit);
      googleLogo(map, this._kind === 'roadmap' || this._kind === 'terrain');
      googleSession(this._kind).then(function () { self._updateCredit(); }, function (err) { googleFallback(map, err); });
    },
    onRemove: function (map) {
      map.off('moveend', this._credit);
      if (map.attributionControl && this._copy) { map.attributionControl.removeAttribution(this._copy); this._copy = null; }
      googleLogo(map, null);
      L.TileLayer.prototype.onRemove.call(this, map);
    },
    // حقوق Data للمنطقة الظاهرة In Google (شرط in استخدام الخرائط)
    _updateCredit: function () {
      var map = this._map, self = this;
      if (!map) { return; }
      clearTimeout(this._creditTimer);
      this._creditTimer = setTimeout(function () {
        googleSession(self._kind).then(function (s) {
          var b = map.getBounds();
          var q = '?session=' + encodeURIComponent(s.session) + '&key=' + encodeURIComponent(GKEY) + '&zoom=' + Math.round(map.getZoom()) +
            '&north=' + b.getNorth().toFixed(6) + '&south=' + b.getSouth().toFixed(6) + '&east=' + b.getEast().toFixed(6) + '&west=' + b.getWest().toFixed(6);
          return fetch(GAPI + '/tile/v1/viewport' + q).then(function (r) { return r.ok ? r.json() : {}; });
        }).then(function (v) {
          if (!self._map || !map.attributionControl) { return; }
          var text = (v && v.copyright) ? String(v.copyright).replace(/[<>&"]/g, '') : 'Map data © Google';
          if (self._copy) { map.attributionControl.removeAttribution(self._copy); }
          self._copy = text;
          map.attributionControl.addAttribution(text);
        }).catch(function () { /* تبقى الحقوق السابقة */ });
      }, 250);
    }
  });

  // شعار Google أسفل Map (شرط in استخدام الخرائط): أبيض فوق الصور الجوية, وملون فوق Map
  function googleLogo(map, light) {
    var box = map.getContainer().querySelector('.gmaps-logo');
    if (light === null) { if (box) { box.remove(); } return; }
    if (!box) {
      box = document.createElement('span');
      box.className = 'gmaps-logo';
      box.innerHTML = '<img alt="Google" width="59" height="18">';
      map.getContainer().appendChild(box);
    }
    box.querySelector('img').src = 'https://developers.google.com/static/maps/documentation/images/' + (light ? 'google_on_white.png' : 'google_on_non_white.png');
  }

  // Invalid key or Service غير Active: يُعاد to Map Open مع message واحدة
  function googleFallback(map, err) {
    if (!map._snLayers) { return; }
    var open = map._snLayers[STREET];
    Object.keys(map._snLayers).forEach(function (k) { if (map.hasLayer(map._snLayers[k]) && map._snLayers[k] !== open) { map.removeLayer(map._snLayers[k]); } });
    if (!map.hasLayer(open)) { open.addTo(map); }
    if (!googleFailed && window.SN) {
      googleFailed = true;
      SN.toast('warning', 'Google Maps could not load, so the regular map is shown. Check the Google key and enable Map Tiles API.');
    }
    if (window.console) { console.warn('Google Map Tiles:', err && err.message); }
  }

  var STREET = 'Map';
  var G_ROAD = 'Google Maps', G_HYBRID = 'Google Satellite', G_TERRAIN = 'Google Terrain';

  /** طبقات Map: Google Maps (عند ضبط Key), والشوارع والقمر الصناعي Open */
  function baseLayers() {
    var street = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19, className: 'tiles-street',
      attribution: '&copy; OpenStreetMap'
    });
    var imagery = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
      maxZoom: 19, attribution: 'Imagery &copy; Esri'
    });
    var labels = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}', {
      maxZoom: 19, pane: 'overlayPane'
    });
    var out = {};
    if (GKEY) {
      out[G_ROAD] = new GoogleLayer('roadmap');
      out[G_HYBRID] = new GoogleLayer('hybrid');
      out[G_TERRAIN] = new GoogleLayer('terrain');
    }
    out[STREET] = street;
    out['Satellite'] = L.layerGroup([imagery, labels]);
    return out;
  }

  function savedBase() {
    try { return localStorage.getItem('sn-map-base') || ''; } catch (e) { return ''; }
  }

  /** Add Layers للخريطة مع تذكّر Last اختيار (وGoogle Maps أولاً عند ضبط مفتاحها) */
  function attachLayers(map) {
    var layers = baseLayers();
    map._snLayers = layers;
    var name = savedBase();
    if (!layers[name]) { name = GKEY ? G_ROAD : STREET; }
    if (googleFailed && layers[name] instanceof GoogleLayer) { name = STREET; }
    layers[name].addTo(map);
    L.control.layers(layers, null, { position: 'topleft' }).addTo(map);
    map.on('baselayerchange', function (e) {
      try { localStorage.setItem('sn-map-base', e.name); } catch (err) { /* Storage Unavailable */ }
    });
    return layers;
  }

  /** أيقونة Round بأيقونة from Group System */
  function icon(name, cls, size) {
    size = size || 34;
    var iconsUrl = (document.querySelector('meta[name="icons-url"]') || {}).content || '';
    return L.divIcon({
      className: 'mk-wrap',
      html: '<span class="mk ' + (cls || '') + '" style="width:' + size + 'px;height:' + size + 'px">' +
        '<svg class="icon" aria-hidden="true"><use href="' + iconsUrl + '#i-' + name + '"></use></svg></span>',
      iconSize: [size, size],
      iconAnchor: [size / 2, size / 2],
      popupAnchor: [0, -size / 2]
    });
  }

  function dot(cls) {
    return L.divIcon({ className: 'mk-wrap', html: '<span class="mk-dot ' + (cls || '') + '"></span>', iconSize: [14, 14], iconAnchor: [7, 7], popupAnchor: [0, -7] });
  }

  // ------------------------------------------------------------------------
  // محدِّد Location للنماذج: [data-location] يحوي [data-lat] و[data-lng] و[data-pick]
  // ------------------------------------------------------------------------
  var picker = null;

  function buildPicker() {
    var dlg = document.createElement('dialog');
    dlg.className = 'modal modal-lg';
    dlg.id = 'loc-picker';
    dlg.innerHTML =
      '<div class="modal-head"><h3>' + (window.SN ? SN.icon('map-pin') : '') + 'Locate</h3>' +
      '<button type="button" class="btn btn-ghost btn-icon btn-sm" data-modal-close>' + (window.SN ? SN.icon('x') : '×') + '</button></div>' +
      '<div class="modal-body" style="padding:0"><div class="map-picker" data-picker-map></div></div>' +
      '<div class="modal-foot">' +
      '<span class="mini-stat mono" dir="ltr" data-picker-coords>—</span>' +
      '<button type="button" class="btn" data-picker-locate>' + (window.SN ? SN.icon('map-pin') : '') + 'My current location</button>' +
      '<button type="button" class="btn btn-primary" data-picker-ok>' + (window.SN ? SN.icon('check') : '') + 'Confirm</button></div>';
    document.body.appendChild(dlg);
    var map = L.map(dlg.querySelector('[data-picker-map]'), { zoomControl: true, attributionControl: true });
    attachLayers(map);
    var marker = null;
    var state = { lat: null, lng: null, target: null };
    function set(lat, lng, pan) {
      state.lat = Math.round(lat * 1e7) / 1e7;
      state.lng = Math.round(lng * 1e7) / 1e7;
      if (!marker) {
        marker = L.marker([lat, lng], { draggable: true, icon: icon('map-pin', 'is-primary') }).addTo(map);
        marker.on('dragend', function () { var p = marker.getLatLng(); set(p.lat, p.lng, false); });
      } else {
        marker.setLatLng([lat, lng]);
      }
      if (pan) { map.setView([lat, lng], Math.max(map.getZoom(), 16)); }
      dlg.querySelector('[data-picker-coords]').textContent = state.lat.toFixed(6) + ', ' + state.lng.toFixed(6);
    }
    map.on('click', function (e) { set(e.latlng.lat, e.latlng.lng, false); });
    var locate = dlg.querySelector('[data-picker-locate]');
    if (!navigator.geolocation || !window.isSecureContext) { locate.hidden = true; }
    locate.addEventListener('click', function () {
      locate.disabled = true;
      navigator.geolocation.getCurrentPosition(function (pos) {
        locate.disabled = false;
        set(pos.coords.latitude, pos.coords.longitude, true);
      }, function () {
        locate.disabled = false;
        if (window.SN) { SN.toast('error', 'Could not determine your location.'); }
      }, { enableHighAccuracy: true, timeout: 15000 });
    });
    dlg.querySelector('[data-picker-ok]').addEventListener('click', function () {
      if (state.target && state.lat !== null) {
        state.target.querySelector('[data-lat]').value = state.lat;
        state.target.querySelector('[data-lng]').value = state.lng;
        state.target.querySelector('[data-lat]').dispatchEvent(new Event('change', { bubbles: true }));
      }
      if (window.SN) { SN.closeModal(dlg); } else { dlg.close(); }
    });
    picker = {
      open: function (box) {
        state.target = box;
        var lat = parseFloat(box.querySelector('[data-lat]').value);
        var lng = parseFloat(box.querySelector('[data-lng]').value);
        var def = [31.45, 34.40, 11];
        try { def = JSON.parse(box.getAttribute('data-default')) || def; } catch (e) { /* Default */ }
        if (window.SN) { SN.openModal(dlg); } else { dlg.showModal(); }
        setTimeout(function () {
          map.invalidateSize();
          if (isFinite(lat) && isFinite(lng)) {
            set(lat, lng, false);
            map.setView([lat, lng], 17);
          } else {
            if (marker) { map.removeLayer(marker); marker = null; }
            state.lat = state.lng = null;
            dlg.querySelector('[data-picker-coords]').textContent = '—';
            map.setView([def[0], def[1]], def[2]);
          }
        }, 60);
      }
    };
    return picker;
  }

  document.addEventListener('click', function (e) {
    var btn = e.target.closest('[data-location] [data-pick]');
    if (!btn) { return; }
    e.preventDefault();
    (picker || buildPicker()).open(btn.closest('[data-location]'));
  });

  window.SNGeo = { attachLayers: attachLayers, baseLayers: baseLayers, icon: icon, dot: dot, google: !!GKEY };
})(window, document);
